package local.my0511.lite;
import java.util.*;
import java.util.regex.*;
import org.jsoup.Jsoup;
import org.jsoup.nodes.*;
public final class ForumParser {
 public static final class Topic {public String title,url,tid,author,date,counts;}
 public static final class Floor {public String author,text,pid,time;public List<String> images=new ArrayList<>();}
 public static final class Page {public String title,url;public int totalPages=1;public List<Floor> floors=new ArrayList<>();}
 public static List<Topic> board(String html,String url){return board(html,url,false);}
 public static List<Topic> readerBoard(String html,String url){return board(html,url,true);}
 private static List<Topic> board(String html,String url,boolean hidePinned){Document d=Jsoup.parse(html,url);List<Topic> out=new ArrayList<>();Set<String> seen=new HashSet<>();boolean pinned=false;for(Element row:d.select("dl.list_dl")){Element a=row.selectFirst("a.a_topic[href]");if(a==null){String heading=text(row.selectFirst("dt"));if(heading.contains("版内置顶"))pinned=true;else if(heading.contains("论坛主题"))pinned=false;continue;}if(hidePinned&&(pinned||"镇江直聘网".equals(text(row.selectFirst("dd a.linkblack")))||a.text().startsWith("镇江直聘网今日招聘信息")))continue;String href=a.absUrl("href"),tid=ForumPolicy.threadId(href);if(tid.isEmpty()||!seen.add(tid))continue;Topic t=new Topic();t.title=a.text();t.url=ForumPolicy.thread(tid,1);t.tid=tid;t.author=text(row.selectFirst("dd a.linkblack"));t.date=text(row.selectFirst(".tdate"));t.counts="回复 "+text(row.selectFirst(".fontblue"))+" · 浏览 "+text(row.selectFirst(".tcount"));out.add(t);}return out;}
 public static Page thread(String html,String url){String tid=ForumPolicy.threadId(url);if(tid.isEmpty())throw new IllegalArgumentException("仅支持百姓话题帖子");Document d=Jsoup.parse(html,url);Page p=new Page();p.url=url;p.title=d.title().split(" - ")[0];for(Element a:d.select("a[href]")){String href=a.absUrl("href");if(!tid.equals(ForumPolicy.threadId(href)))continue;Matcher m=Pattern.compile("z-([0-9]+)").matcher(href);if(m.find()&&m.group(1).length()<=6){int page=Integer.parseInt(m.group(1));if(page<=100000)p.totalPages=Math.max(p.totalPages,page);}}for(Element s:d.select("div.outer-section")){Element body=s.selectFirst(".post-content");if(body==null)continue;Floor f=new Floor();f.author=text(s.selectFirst(".conleft a[href*=viewpro]"));f.time=text(s.selectFirst(".connext-left span.dawn-fl"));f.pid="";Element floor=s.selectFirst(".connext-left a.bold");if(floor!=null){Matcher m=Pattern.compile("pid([0-9]+)").matcher(floor.attr("onclick"));if(m.find())f.pid=m.group(1);}for(Element a:s.select("a[href]")){Matcher m=Pattern.compile("#pid([0-9]+)").matcher(a.attr("href"));if(m.find())f.pid=m.group(1);}Element clone=body.clone();clone.select("script,style,.mobilestr").remove();for(Element img:clone.select("img")){String src=img.hasAttr("data-src")?img.absUrl("data-src"):img.absUrl("src");if(src.startsWith("https://"))f.images.add(src);img.after("[图片]");img.remove();}clone.select("br").append("\n");clone.select("p,div,blockquote").prepend("\n").append("\n");f.text=clone.wholeText().replaceAll("[ \\t]+"," ").replaceAll("\\n{3,}","\n\n").trim();p.floors.add(f);}return p;}
 public static String text(Element e){return e==null?"":e.text();}
 public static String norm(String s){return s==null?"":s.replaceAll("\\s+","");}
 public static String receipt(Page p,Task t,String author,Set<String> previousPids){if(author.trim().isEmpty()||p.floors.isEmpty())return "";String tid=ForumPolicy.threadId(p.url);if(t.reply&&!tid.equals(t.tid))return "";if(!t.reply&&!norm(p.title).equals(norm(t.title)))return "";for(Floor f:p.floors){if(!author.equals(f.author)||f.pid.isEmpty()||previousPids.contains(f.pid))continue;if(norm(f.text).equals(norm(t.message)))return ForumPolicy.thread(tid,1)+"#pid"+f.pid;}return "";}
}
